vec4 tex(vec2 uv){
return texture(iChannel0,uv/iResolution.xy,0.0);
}
float grid(vec2 uv){
return step(sin(uv.x/20.0)*sin(uv.y/20.0),0.0);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

float mid=tex(fragCoord).g;
float dx=tex(fragCoord+vec2(1.0,0.0)).g;
float dy=tex(fragCoord+vec2(0.0,1.0)).g;
vec2 grad=vec2(mid-dx,mid-dy);
fragColor.rgb=vec3(grid(fragCoord+grad*1000.0))*mid;
fragColor.rgb+=(grad.rgg*100.0)*mid;
float sound=0.0;//tex(fragCoord).b;
for(float i=0.0;i<160.0;i+=2.0){
sound+=texelFetch( iChannel1, ivec2(i+200.0,0), 0 ).x;
}
sound/=80.0;
sound-=0.3;
fragColor.g+=sound;
    fragColor.a=1.0;
}

vec4 tex(vec2 uv){
return texelFetch(iChannel0,ivec2(uv)%ivec2(iResolution.xy),0)*2.0-1.0;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;


vec4 avg=vec4(0.0);

avg/=1.0;
fragColor.rgba=tex(fragCoord).rgba;
float c=0.02;
float h=3.0;
float x=fragCoord.x;
float y=fragCoord.y;
float d2u = tex(vec2(x +h,y)).g - 2.0*tex(vec2(x,y)).g + tex(vec2(x-h,y)).g;
float d2u2 = tex(vec2(x,y+h)).g - 2.0*tex(vec2(x,y)).g + tex(vec2(x,y-h)).g;
float d2t = 0.001; // small step
float acc = c * c * ((d2u / d2t)+(d2u2 / d2t));
fragColor.r+=acc;
fragColor.g+=fragColor.r;
fragColor.rg*=0.99;
if(iFrame==0){
fragColor.rgba=vec4(0.0,0.0,0.0,0.0);
}
float sound=0.0;//tex(fragCoord).b;
for(float i=0.0;i<120.0;i+=2.0){
sound+=texelFetch( iChannel1, ivec2(i,0), 0 ).x;
}
sound/=60.0;
sound-=0.4;

fragColor.a=mix(tex(fragCoord).a,sound,0.9);
fragColor.b+=fragColor.a/1.0;
fragColor.b*=0.1;
if(length(fragCoord-iResolution.xy*0.5)<50.0||sin(fragCoord.y/20.0)*5.0+fragCoord.x<10.0||sin(fragCoord.y/20.0)*5.0+(fragCoord.x-iResolution.x+20.0)>10.0){
fragColor.rgba=vec4(fragColor.r,fragColor.b*20.0,fragColor.b,fragColor.a);
}
fragColor.rgba=fragColor.rgba*0.5+0.5;


}
